static void queue(Context context){
  Log.i("Queuing " + getName() + " every "+ CLEANUP_INTERVAL+ " hours");
  PeriodicWorkRequest workRequest=new PeriodicWorkRequest.Builder(WorkerCleanup.class,CLEANUP_INTERVAL,TimeUnit.HOURS).build();
  WorkManager.getInstance(context).enqueueUniquePeriodicWork(getName(),ExistingPeriodicWorkPolicy.REPLACE,workRequest);
  Log.i("Queued " + getName());
}
